#include "Monstey_NavSeamAlternate.hpp"
#include "Monstey_Core.hpp"
#include <cmath>
#include <cstring>
#include <iostream>
#include <random>
using namespace Monstey;
namespace {
using V=Monstey_NavSeamVector4;using M=Monstey_NavigationBoundaryMeshView;using J=Monstey_Json;
struct Mesh{Monstey_Bytes faces=Monstey_Bytes(16),edges=Monstey_Bytes(80),vertices=Monstey_Bytes(64);std::array<std::int32_t,1>fm{-1};std::array<std::int32_t,4>em{-1,-1,-1,-1};M View()const{M m{};m.faces=faces;m.edges=edges;m.vertices=vertices;m.face_map=fm;m.edge_map=em;m.transform={V{1,0,0,0},V{0,1,0,0},V{0,0,1,0},V{0,0,0,0}};return m;}};
Mesh Quad(const std::array<V,4>&p){Mesh m;Monstey_PutU16(m.faces,8,4);for(unsigned i=0;i<4;++i){Monstey_PutU32(m.edges,i*20,i);Monstey_PutU32(m.edges,i*20+4,(i+1)%4);Monstey_PutU32(m.edges,i*20+8,0xffffffff);Monstey_PutU32(m.edges,i*20+12,0xffffffff);std::memcpy(m.vertices.data()+i*16,p[i].data(),16);}return m;}
}
int wmain(int argc,wchar_t**argv){try{Monstey_Require(argc==2,"Usage: NEW_REPORT");unsigned cases=0,groups=0;std::mt19937 random(0x3bf31c);std::uniform_real_distribution<float>range(-1,1),positive(.5f,2);auto Check=[&](const M&m,std::uint32_t face,const std::array<std::int32_t,4>&indices){std::array<V,4>points{};for(unsigned i=0;i<4;++i)points[i]=Monstey_NavigationBoundaryWorldVertex(m,indices[i]);std::array<double,3>n{};for(unsigned i=0;i<4;++i){const auto&p=points[i];const auto&q=points[(i+1)%4];n[0]+=(static_cast<double>(p[1])-q[1])*(static_cast<double>(p[2])+q[2]);n[1]+=(static_cast<double>(p[2])-q[2])*(static_cast<double>(p[0])+q[0]);n[2]+=(static_cast<double>(p[0])-q[0])*(static_cast<double>(p[1])+q[1]);}const double length=std::sqrt(n[0]*n[0]+n[1]*n[1]+n[2]*n[2]);const auto got=Monstey_NavSeamFaceNormal(m,face);for(unsigned axis=0;axis<3;++axis)Monstey_Require(std::abs(got.normal[axis]-n[axis]/length)<.00003,"Native face normal differs from independent Newell reference");for(float area:got.area)Monstey_Require(std::abs(area-length*.5)<.00003*(1+length),"Native face area differs from independent Newell reference");++cases;};for(unsigned c=0;c<1024;++c){V origin{range(random),range(random),range(random),range(random)},u{2+.3f*range(random),.2f*range(random),.2f*range(random),0},v{.2f*range(random),.2f*range(random),-2+.3f*range(random),0};std::array<V,4>points{};for(unsigned axis=0;axis<4;++axis){points[0][axis]=origin[axis];points[1][axis]=origin[axis]+u[axis];points[2][axis]=origin[axis]+u[axis]+v[axis];points[3][axis]=origin[axis]+v[axis];}auto owned=Quad(points);auto mesh=owned.View();mesh.transform={V{positive(random),.1f*range(random),.1f*range(random),.1f*range(random)},V{.1f*range(random),positive(random),.1f*range(random),.1f*range(random)},V{.1f*range(random),.1f*range(random),positive(random),.1f*range(random)},V{20*range(random),20*range(random),20*range(random),20*range(random)}};Check(mesh,0,{0,1,2,3});}++groups;auto owned=Quad({V{0,0,0,11},V{2,0,0,13},V{2,0,-2,17},V{0,0,-2,19}});auto mapped=owned.View();std::array<std::int32_t,1>fm{0};std::array<std::int32_t,4>em{0,1,2,3};mapped.face_map=fm;mapped.edge_map=em;mapped.mapped_faces=owned.faces;mapped.mapped_edges=owned.edges;Check(mapped,0,{0,1,2,3});++groups;std::array<std::int32_t,4>rotate{1,2,3,0};mapped.edge_map=rotate;Check(mapped,0,{0,1,2,3});++groups;Monstey_Bytes addedFaces=owned.faces,addedEdges=owned.edges,addedVertices=owned.vertices;Monstey_PutU32(addedFaces,0,4);for(unsigned i=0;i<4;++i){Monstey_PutU32(addedEdges,i*20,4+i);Monstey_PutU32(addedEdges,i*20+4,4+(i+1)%4);}auto added=owned.View();added.added_faces=addedFaces;added.added_edges=addedEdges;added.added_vertices=addedVertices;Check(added,1,{4,5,6,7});++groups;Monstey_WriteNewText(argv[1],J::object({{"status","PASS"},{"groups",groups},{"owned_normal_area_cases",cases},{"independent_Newell_cases",1024},{"mapped_and_added_cases",3},{"original_program_called",false},{"process_accessed",false}}).dump(2)+"\n");std::cout<<"PASS "<<cases<<" face normal/area reference cases\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}